            if self.spy_sma_200.IsReady and self.spy_sma_200_previous is not None:
                spy_close = bars[self.spy].Close
                spy_sma_200 = self.spy_sma_200.Current.Value
                spy_buy_signal = (
                    self.spy_previous_close is not None
                    and self.spy_previous_close <= self.spy_sma_200_previous
                    and spy_close > spy_sma_200
                )

            if self.spy_sma_50.IsReady and self.spy_sma_50_previous is not None:
                spy_close = bars[self.spy].Close
                spy_sma_50 = self.spy_sma_50.Current.Value
                spy_sell_signal = (
                    self.spy_previous_close is not None
                    and self.spy_previous_close >= self.spy_sma_50_previous
                    and spy_close < spy_sma_50
                )

            if self.aapl_rsi_14.IsReady:
                aapl_sell_signal = self.aapl_rsi_14.Current.Value > 60

            if not self.IsWarmingUp:
                if self.strategy_a_lot > 0 and spy_sell_signal:
                    ticket = self.MarketOrder(
                        self.spy,
                        -self.strategy_a_lot,
                        tag="Strategy A sell"
                    )
                    if ticket is not None and ticket.Status not in (
                        OrderStatus.Invalid,
                        OrderStatus.Canceled
                    ):
                        self.strategy_a_lot = 0

                if self.strategy_b_lot > 0 and aapl_sell_signal:
                    ticket = self.MarketOrder(
                        self.aapl,
                        -self.strategy_b_lot,
                        tag="Strategy B sell"
                    )
                    if ticket is not None and ticket.Status not in (
                        OrderStatus.Invalid,
                        OrderStatus.Canceled
                    ):
                        self.strategy_b_lot = 0

                if self.strategy_a_lot == 0 and spy_buy_signal:
                    spy_close = float(bars[self.spy].Close)
                    quantity = int(
                        (0.40 * float(self.Portfolio.TotalPortfolioValue))
                        / spy_close
                    )

                    if quantity > 0:
                        ticket = self.MarketOrder(
                            self.spy,
                            quantity,
                            tag="Strategy A buy"
                        )
                        if ticket is not None and ticket.Status not in (
                            OrderStatus.Invalid,
                            OrderStatus.Canceled
                        ):
                            self.strategy_a_lot = quantity

                if (
                    self.strategy_b_lot == 0
                    and self.aapl_red_streak >= 3
                ):
                    aapl_close = float(bars[self.aapl].Close)
                    available_cash = float(self.Portfolio.Cash)

                    if available_cash >= 20000:
                        quantity = int(20000 / aapl_close)

                        if quantity > 0:
                            ticket = self.MarketOrder(
                                self.aapl,
                                quantity,
                                tag="Strategy B buy"
                            )
                            if ticket is not None and ticket.Status not in (
                                OrderStatus.Invalid,
                                OrderStatus.Canceled
                            ):
                                self.strategy_b_lot = quantity

        if present[self.spy]:
            self.spy_previous_close = bars[self.spy].Close

            if self.spy_sma_200.IsReady:
                self.spy_sma_200_previous = self.spy_sma_200.Current.Value

            if self.spy_sma_50.IsReady:
                self.spy_sma_50_previous = self.spy_sma_50.Current.Value
