from AlgorithmImports import *
from collections import deque
import math


class MainAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.closes = {
            symbol: deque(maxlen=201)
            for symbol in self.symbols
        }

        self.aapl_red_streak = 0
        self.aapl_previous_close = None

        self.aapl_rsi = self.RSI(
            self.aapl,
            14,
            MovingAverageType.Wilders,
            Resolution.Daily
        )

        self.a_lot = 0
        self.b_lot = 0

        self.pending_orders = {}

        self.SetWarmUp(201, Resolution.Daily)

    def OnData(self, data):
        bars = {}

        for symbol in self.symbols:
            if data.Bars.ContainsKey(symbol):
                bars[symbol] = data.Bars[symbol]

        for symbol, bar in bars.items():
            close = float(bar.Close)
            self.closes[symbol].append(close)

            if symbol == self.aapl:
                if self.aapl_previous_close is not None:
                    if close < self.aapl_previous_close:
                        self.aapl_red_streak += 1
                    else:
                        self.aapl_red_streak = 0

                self.aapl_previous_close = close

        if self.IsWarmingUp:
            return

        if len(bars) != len(self.symbols):
            return

        self._evaluate_sells(bars)
        self._evaluate_buys(bars)

    def _evaluate_sells(self, bars):
        if (
            self.a_lot > 0
            and not self._has_pending_order("A", "sell")
            and self._crosses_below(self.spy, 50)
        ):
            self._submit_order("A", "sell", self.spy, -self.a_lot, "Strategy A Sell")

        if (
            self.b_lot > 0
            and not self._has_pending_order("B", "sell")
            and self.aapl_rsi.IsReady
            and float(self.aapl_rsi.Current.Value) > 60
        ):
            self._submit_order("B", "sell", self.aapl, -self.b_lot, "Strategy B Sell")

    def _evaluate_buys(self, bars):
        if (
            self.a_lot == 0
            and not self._has_pending_order("A", "buy")
            and self._crosses_above(self.spy, 200)
        ):
            close = float(bars[self.spy].Close)
            target_value = 0.40 * float(self.Portfolio.TotalPortfolioValue)
            quantity = int(math.floor(target_value / close))

            if quantity > 0:
                self._submit_order("A", "buy", self.spy, quantity, "Strategy A Buy")

        if (
            self.b_lot == 0
            and not self._has_pending_order("B", "buy")
            and self.aapl_red_streak >= 3
        ):
            close = float(bars[self.aapl].Close)
            available_cash = float(self.Portfolio.Cash)
            required_cash = 20000.0

            if available_cash >= required_cash:
                quantity = int(math.floor(required_cash / close))

                if quantity > 0:
                    self._submit_order("B", "buy", self.aapl, quantity, "Strategy B Buy")

    def _crosses_above(self, symbol, period):
        values = list(self.closes[symbol])

        if len(values) < period + 1:
            return False

        yesterday_sma = sum(values[-period-1:-1]) / period
        today_sma = sum(values[-period:]) / period

        return (
            values[-2] <= yesterday_sma
            and values[-1] > today_sma
        )

    def _crosses_below(self, symbol, period):
        values = list(self.closes[symbol])

        if len(values) < period + 1:
            return False

        yesterday_sma = sum(values[-period-1:-1]) / period
        today_sma = sum(values[-period:]) / period

        return (
            values[-2] >= yesterday_sma
            and values[-1] < today_sma
        )

    def _submit_order(self, strategy, action, symbol, quantity, tag):
        ticket = self.MarketOrder(symbol, quantity, tag)

        if ticket is not None:
            self.pending_orders[ticket.OrderId] = {
                "strategy": strategy,
                "action": action
            }

    def _has_pending_order(self, strategy, action):
        return any(
            details["strategy"] == strategy
            and details["action"] == action
            for details in self.pending_orders.values()
        )

    def OnOrderEvent(self, order_event):
        order_id = order_event.OrderId

        if order_id not in self.pending_orders:
            return

        details = self.pending_orders[order_id]
        fill_quantity = int(order_event.FillQuantity)

        if fill_quantity != 0:
            if details["strategy"] == "A":
                self.a_lot = max(0, self.a_lot + fill_quantity)
            else:
                self.b_lot = max(0, self.b_lot + fill_quantity)

        if order_event.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ):
            del self.pending_orders[order_id]
